B.akC=new A.aW("D\u011bda Bohou\u0161 dnes slav\xed sedmdes\xe1t\xe9 narozeniny. D\u016fm je pln\xfd p\u0159\xedbuzn\xfdch, von\xed tu sv\xed\u010dkov\xe1 a dort a v\u0161ude cinkaj\xed skleni\u010dky. Teta Jarmila \u0161t\xedpe do tv\xe1\u0159\xed ka\u017ed\xe9ho, kdo se nestihne schovat. Str\xfdc Pepa u\u017e pot\u0159et\xed vypr\xe1v\xed o hypot\xe9k\xe1ch. A d\u011bda sed\xed v \u010dele stolu a usm\xedv\xe1 se pod vousy.")
B.bha=new A.C(56,56)
B.e4=new A.kp("K","klara","")
B.ado=s(["\u201eTohle je ofici\xe1ln\u011b nejnudn\u011bj\u0161\xed oslava na sv\u011bt\u011b. Spo\u010d\xedtala jsem to. Str\xfdc \u0159ekl slovo hypot\xe9ka dvaa\u010dty\u0159icetkr\xe1t.\u201c"],t.s)
B.aZU=new A.a6(B.e4,B.ado,!1)
B.eK=new A.kp("T","tobi","")
B.abh=s(["\u201eTeta m\u011b \u0161t\xedpla u\u017e p\u011btkr\xe1t. Za chv\xedli budu m\xedt tv\xe1\u0159e jako dv\u011b raj\u010data.\u201c"],t.s)
B.b1q=new A.a6(B.eK,B.abh,!1)
B.a4d=s(["\u201eJako dv\u011b mal\xe1 kysel\xe1 raj\u010d\xe1tka.\u201c"],t.s)
B.b_W=new A.a6(B.e4,B.a4d,!1)
B.a60=s(["\u201eNejsem kysel\xfd!\u201c"],t.s)
B.b1R=new A.a6(B.eK,B.a60,!1)
B.ald=new A.aW("Kl\xe1ra se rozhl\xe9dne a uk\xe1\u017ee ke schod\u016fm. Vedou nahoru, a\u017e pod st\u0159echu. Na p\u016fdu, kam nikdo nechod\xed.")
B.agi=s(["\u201eMiz\xedme. Hned te\u010f.\u201c"],t.s)
B.b_8=new A.a6(B.e4,B.agi,!1)
B.a5E=s([B.akC,B.aZU,B.b1q,B.b_W,B.b1R,B.ald,B.b_8],t.a)
B.b2n=new A.cv("story_01",B.a5E)
B.alx=new A.aW("Kl\xe1ra, Tobi a ty cupit\xe1te po schodech nahoru. Dup, dup, dup. A za v\xe1mi \u0165apkaj\xed \u010dty\u0159i tlapky. Pes Ferda p\u0159ece nebude chyb\u011bt u \u017e\xe1dn\xe9 lump\xe1rny!")
B.a8X=s(["\u201eJ\xe1 prvn\xed!\u201c"],t.s)
B.b_L=new A.a6(B.eK,B.a8X,!1)
B.aed=s(["\u201eNe, j\xe1!\u201c"],t.s)
B.b_a=new A.a6(B.e4,B.aed,!1)
B.alQ=new A.aW("Dve\u0159e na p\u016fdu zavrzaj\xed. Vrrrrz. Je tu \u0161ero a ve sv\u011btle z ok\xe9nka tan\u010d\xed prach. U st\u011bny stoj\xed reg\xe1l se star\xfdmi plechovkami. Na tr\xe1mu vis\xed kalend\xe1\u0159 s traktorem. A uprost\u0159ed stoj\xed velk\xe1 zelen\xe1 bedna s \u010derven\xfdm p\xedsmenem B.")
B.abg=s(["\u201e\u201aNEOTEV\xcdRAT!\u2018 \u2026 A pod t\xedm malink\xfdmi p\xedsmenky: \u201akrom\u011b pr\u016fzkumn\xedk\u016f\u2018.\u201c"],t.s)
B.aZV=new A.a6(B.eK,B.abg,!1)
B.aeo=s(["\u201eKrom\u011b pr\u016fzkumn\xedk\u016f. To jsme p\u0159ece my.\u201c"],t.s)
B.b00=new A.a6(B.e4,B.aeo,!1)
B.alo=new A.aW("Ferda zavrt\xed ocasem a k\xfdchne. Hep\u010d\xed! Na v\xedku bedny je ale kulat\xfd z\xe1mek. A kl\xed\u010d nikde.")
B.a7r=s([B.alx,B.b_L,B.b_a,B.alQ,B.aZV,B.b00,B.alo],t.a)
B.b2A=new A.cv("story_02",B.a7r)
B.alP=new A.aW("Cvak! V\xedko bedny se zvedne a vylet\xed z n\xed oblak prachu. Puf! V\u0161ichni k\xfdchnete najednou. Hep\u010d\xed! Hep\u010d\xed! Haf!")
B.akF=new A.aW("Uvnit\u0159 je hromada pap\xedrov\xfdch \xfatr\u017ek\u016f. Star\xe9 dopisy, se\u0161ity, kousky obr\xe1zk\u016f. Najednou se hromada pohne. A z pap\xedr\u016f vyklouzne mal\xe1 \u0161ed\xe1 my\u0161!")
B.acM=s(["\u201e\xcd\xed\xed\xed! My\u0161!\u201c"],t.s)
B.b_Q=new A.a6(B.eK,B.acM,!1)
B.aln=new A.aW("My\u0161 prob\u011bhne Ferdovi mezi tlapkami a zmiz\xed pod tr\xe1mem. A Ferda? Velk\xfd state\u010dn\xfd hl\xedda\u010d se schov\xe1 za Kl\xe1ru a cel\xfd se t\u0159ese.")
B.adm=s(["\u201eFerdo, ty jsi ale hrdina. Boj\xed\u0161 se my\u0161i, kter\xe1 je men\u0161\xed ne\u017e tvoje miska.\u201c"],t.s)
B.b18=new A.a6(B.e4,B.adm,!1)
B.a5K=s(["\u201eJ\xe1 jsem se neb\xe1l. Jenom jsem ji\u2026 hlasit\u011b pozdravil.\u201c"],t.s)
B.b_c=new A.a6(B.eK,B.a5K,!1)
B.a9w=s([B.alP,B.akF,B.b_Q,B.aln,B.b18,B.b_c],t.a)
B.b2M=new A.cv("story_03",B.a9w)
B.aaj=s(["\u201ePo\u010dkejte. V kalend\xe1\u0159i byl zakrou\u017ekovan\xfd jednadvac\xe1t\xfd z\xe1\u0159\xed. A dneska je\u2026 dneska je p\u0159ece jednadvac\xe1t\xe9ho z\xe1\u0159\xed! To m\xe1 d\u011bda narozeniny!\u201c"],t.s)
B.b1_=new A.a6(B.e4,B.aaj,!1)
B.akl=new A.aW("Kl\xe1ra se pod\xedv\xe1 na velk\xe9 \u010derven\xe9 B na v\xedku.")
B.afd=s(["\u201eB jako Bohou\u0161. Ta bedna je d\u011bdova!\u201c"],t.s)
B.b0q=new A.a6(B.e4,B.afd,!1)
B.akP=new A.aW("Tobi zat\xedm opatrn\u011b p\u0159eb\xedr\xe1 \xfatr\u017eky pap\xedru. Jeden je jin\xfd ne\u017e ostatn\xed. Je \u010dtvere\u010dkovan\xfd a je na n\u011bm kresba pastelkou: kousek cesti\u010dky, mal\xfd stromek a velk\xfd \u010dern\xfd k\u0159\xed\u017eek.")
B.a8e=s(["\u201eKl\xe1ro\u2026 to je kousek mapy. Mapy k pokladu!\u201c"],t.s)
B.b_A=new A.a6(B.eK,B.a8e,!1)
B.aev=s(["\u201eNebo n\xe1kupn\xed seznam. K\u0159\xed\u017eek znamen\xe1 rohl\xedky.\u201c"],t.s)
B.b0R=new A.a6(B.e4,B.aev,!1)
B.ads=s(["\u201eNa n\xe1kupn\xed seznam se p\u0159ece nekresl\xed stromky!\u201c"],t.s)
B.b14=new A.a6(B.eK,B.ads,!1)
B.alt=new A.aW("Jen\u017ee kde je zbytek mapy? Pap\xedr\u016f je v bedn\u011b cel\xe1 hromada. A my\u0161 si z nich ud\u011blala hn\xedzdo.")
B.abV=s([B.b1_,B.akl,B.b0q,B.akP,B.b_A,B.b0R,B.b14,B.alt],t.a)
B.b2W=new A.cv("story_04",B.abV)
