B.cT=new A.x8(3,"decal")
B.zI=s([B.J,B.v2,B.v3,B.cT],A.aa("r<x8>"))
B.al8=new A.aW("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.ce=new A.kp(null,"marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a5D=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.aZW=new A.a6(B.ce,B.a5D,!1)
B.bs=new A.kp(null,"karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.a9i=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.b0j=new A.a6(B.bs,B.a9i,!1)
B.afO=s([B.al8,B.aZW,B.b0j],t.a)
B.b2H=new A.cv("story_00_intro",B.afO)
B.akz=new A.aW("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.a6q=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.b0f=new A.a6(B.ce,B.a6q,!1)
B.alg=new A.aW("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.a6z=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.b1w=new A.a6(B.bs,B.a6z,!1)
B.cl=new A.kp(null,"tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.aeS=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.b_k=new A.a6(B.cl,B.aeS,!1)
B.a6O=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.b04=new A.a6(B.ce,B.a6O,!1)
B.agy=s([B.akz,B.b0f,B.alg,B.b1w,B.b_k,B.b04],t.a)
B.b2j=new A.cv("story_01a_clubhouse_arrival",B.agy)
B.a7V=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.b_y=new A.a6(B.ce,B.a7V,!1)
B.a9E=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.b_n=new A.a6(B.cl,B.a9E,!1)
B.a4D=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.b_H=new A.a6(B.bs,B.a4D,!1)
B.a6v=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.b0Z=new A.a6(B.cl,B.a6v,!1)
B.a5G=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.b_i=new A.a6(B.bs,B.a5G,!1)
B.a3w=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.b0k=new A.a6(B.ce,B.a3w,!1)
B.abX=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.b0t=new A.a6(B.bs,B.abX,!1)
B.afB=s([B.b_y,B.b_n,B.b_H,B.b0Z,B.b_i,B.b0k,B.b0t],t.a)
B.b2T=new A.cv("story_01b_legend_and_time",B.afB)
B.alL=new A.aW("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.a8_=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.b_T=new A.a6(B.bs,B.a8_,!1)
B.a7n=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.b1d=new A.a6(B.cl,B.a7n,!1)
B.afC=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.b_g=new A.a6(B.bs,B.afC,!1)
B.abx=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.b_J=new A.a6(B.cl,B.abx,!1)
B.a5o=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.b1m=new A.a6(B.ce,B.a5o,!1)
B.acz=s([B.alL,B.b_T,B.b1d,B.b_g,B.b_J,B.b1m],t.a)
B.b2q=new A.cv("story_02_torn_map",B.acz)
B.a4E=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.b0z=new A.a6(B.ce,B.a4E,!1)
B.aco=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.b0L=new A.a6(B.bs,B.aco,!1)
B.akW=new A.aW("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.aeX=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.b1Q=new A.a6(B.cl,B.aeX,!1)
B.afe=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.b0N=new A.a6(B.bs,B.afe,!1)
B.ab0=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.b0h=new A.a6(B.ce,B.ab0,!1)
B.a51=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.b1F=new A.a6(B.bs,B.a51,!1)
B.a7A=s([B.b0z,B.b0L,B.akW,B.b1Q,B.b0N,B.b0h,B.b1F],t.a)
B.b2o=new A.cv("story_03_founders_trail",B.a7A)
B.akB=new A.aW("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.a70=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.b1v=new A.a6(B.bs,B.a70,!1)
B.abR=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.b_l=new A.a6(B.cl,B.abR,!1)
B.aeD=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.b0u=new A.a6(B.bs,B.aeD,!1)
B.a8i=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.b_w=new A.a6(B.ce,B.a8i,!1)
B.a9Q=s([B.akB,B.b1v,B.b_l,B.b0u,B.b_w],t.a)
B.b2w=new A.cv("story_04_flowers_in_mud",B.a9Q)
B.al0=new A.aW("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.a66=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.b06=new A.a6(B.bs,B.a66,!1)
B.a3B=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.b0S=new A.a6(B.cl,B.a3B,!1)
B.a8Q=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.b0a=new A.a6(B.bs,B.a8Q,!1)
B.agl=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.b0Y=new A.a6(B.ce,B.agl,!1)
B.a8E=s([B.al0,B.b06,B.b0S,B.b0a,B.b0Y],t.a)
B.b2z=new A.cv("story_05_old_oak",B.a8E)
B.akX=new A.aW("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.act=s(["\u201eCo se to stalo?\u201c"],t.s)
B.b_K=new A.a6(B.bs,B.act,!1)
B.a8G=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.b0w=new A.a6(B.ce,B.a8G,!1)
B.a6f=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.b1G=new A.a6(B.bs,B.a6f,!1)
B.a9k=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.b_4=new A.a6(B.ce,B.a9k,!1)
B.akI=new A.aW("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.a8U=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.b0e=new A.a6(B.cl,B.a8U,!1)
