B.b1c=new A.a6(B.ce,B.aaO,!1)
B.abr=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.b1j=new A.a6(B.cl,B.abr,!1)
