B.a9M=s(["budik_T_a1","budik_L_a2","budik_C_a3","budik_R_a4","budik_B_a5"],t.s)
B.al7=new A.aW("Je \u010dtvrtek odpoledne a t\u0159\xedda je na v\xfdlet\u011b v muzeu. Vstupn\xed hala je pln\xe1 d\u011bt\xed. Dupou po schodech, \u0161eptaj\xed si a sm\u011bj\xed se. Ema, Jon\xe1\u0161, Nela a ty se zastav\xedte u velk\xe9ho obrazu u hlavn\xedch dve\u0159\xed. Je na n\u011bm vzne\u0161en\xe1 d\xe1ma v \u0161atech, kter\xe1 sp\xed. A tv\xe1\u0159\xed se p\u011bkn\u011b nerudn\u011b.")
B.aE=new A.kp(null,"ema","assets/images/stories/museum/story/portrait_ema.webp")
B.a8L=s(["\u201e\u201aBaronka Frida von\u2026 Schla\u2026 Scho\u2026 Schovanburger.\u2018 Schovan\xfd burger? Kter\xfd bl\xe1zen by schov\xe1val burger?\u201c"],t.s)
B.b1E=new A.a6(B.aE,B.a8L,!1)
B.aK=new A.kp(null,"jonas","assets/images/stories/museum/story/portrait_jonas.webp")
B.a85=s(["\u201eSchlafenberg, Emo. \u017d\xe1dn\xfd schovan\xfd burger. Schlafen je n\u011bmecky sp\xe1t a Berg je hora. Kdy\u017e si to p\u0159elo\u017e\xed\u0161, tak je to Baronka ze Spac\xed hory.\u201c"],t.s)
B.b_6=new A.a6(B.aK,B.a85,!1)
B.aP=new A.kp(null,"nela","assets/images/stories/museum/story/portrait_nela.webp")
B.adM=s(["\u201eTak to se na t\xe9 ho\u0159e asi moc dob\u0159e nesp\xed. Vypad\xe1, \u017ee nespala celou v\u011b\u010dnost.\u201c"],t.s)
B.b1a=new A.a6(B.aP,B.adM,!1)
B.als=new A.aW("Pod jm\xe9nem baronky vis\xed je\u0161t\u011b jedna men\u0161\xed cedulka.")
B.a65=s(["\u201e\u201aZ\xedtra r\xe1no se obraz st\u011bhuje do nov\xe9 galerie na hlavn\xedm n\xe1dra\u017e\xed.\u2018\u201c"],t.s)
B.b1r=new A.a6(B.aE,B.a65,!1)
B.alu=new A.aW("Jon\xe1\u0161 by p\u0159\xedsahal, \u017ee se baronka v tu chv\xedli zamra\u010dila je\u0161t\u011b v\xedc.")
B.a5C=s([B.al7,B.b1E,B.b_6,B.b1a,B.als,B.b1r,B.alu],t.a)
B.b2x=new A.cv("story_01",B.a5C)
B.akL=new A.aW("Kdy\u017e exkurze skon\u010d\xed, v\u0161ichni sp\u011bchaj\xed k autobusu. Teda t\xe9m\u011b\u0159 v\u0161ichni.")
B.a99=s(["\u201ePsst. M\xe1m pl\xe1n. Schov\xe1me se v \u0161atn\u011b a muzeum bude v noci jen na\u0161e.\u201c"],t.s)
B.b1T=new A.a6(B.aE,B.a99,!1)
B.a7N=s(["\u201eTo je ten nejhor\u0161\xed pl\xe1n, jak\xfd jsem kdy sly\u0161el.\u201c"],t.s)
B.b_E=new A.a6(B.aK,B.a7N,!1)
B.akA=new A.aW("Autobus odjede. Muzeum se zav\u0159e a sv\u011btla zhasnou. V\u0161echny hodiny v muzeu se v tu chv\xedli zastav\xed a ru\u010di\u010dky sko\u010d\xed na p\u016flnoc.")
B.adS=s(["\u201eZavol\xe1m dom\u016f, \u017ee se exkurze trochu prot\xe1hne. Hm. Nem\xe1m sign\xe1l, ani \u010d\xe1rku.\u201c"],t.s)
B.b1x=new A.a6(B.aP,B.adS,!1)
B.a82=s(["\u201eA vstupn\xed dve\u0159e jsou zam\u010den\xe9! Jako by n\xe1s muzeum necht\u011blo pustit ven.\u201c"],t.s)
B.b_3=new A.a6(B.aK,B.a82,!1)
B.akG=new A.aW("A d\u011bti poprv\xe9 napadne, \u017ee se odsud mo\u017en\xe1 nedostanou. Ani dnes. Ani nikdy.")
B.a3W=s(["\u201eTak nebudeme \u010dekat. Prozkoum\xe1me to tu. Jenom pot\u0159ebujeme sv\u011btlo.\u201c"],t.s)
B.b0C=new A.a6(B.aE,B.a3W,!1)
B.akK=new A.aW("V muzeu je prapodivn\xe9 ticho. V \u0161atn\u011b na zdi nejist\u011b blik\xe1 lampa. Nela najde u dve\u0159\xed star\xfd oto\u010dn\xfd vyp\xedna\u010d a zku\u0161en\u011b s n\xedm p\xe1rkr\xe1t cvakne. Lampa zaprask\xe1, zablik\xe1 a rozsv\xedt\xed se naplno.")
B.a8p=s([B.akL,B.b1T,B.b_E,B.akA,B.b1x,B.b_3,B.akG,B.b0C,B.akK],t.a)
B.b2E=new A.cv("story_02",B.a8p)
B.al9=new A.aW("Posledn\xed sk\u0159\xed\u0148ka se s vrznut\xedm otev\u0159e a na zem vypadne sto\u010den\xfd svitek. Je to pl\xe1nek muzea, nakreslen\xfd rukou. Na druh\xe9 stran\u011b je n\u011bco naps\xe1no rozt\u0159esen\xfdm p\xedsmem.")
B.a73=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d. Nev\u011b\u0159te jej\xedmu \xfasm\u011bvu. V. T.\u2018\u201c"],t.s)
B.b1k=new A.a6(B.aK,B.a73,!1)
B.abD=s(["\u201eKdo je V. T.? A jak\xe9mu \xfasm\u011bvu?\u201c"],t.s)
B.b1K=new A.a6(B.aE,B.abD,!1)
B.ade=s(["\u201eSuper. Jsme zam\u010den\xed v muzeu a dost\xe1v\xe1me podivn\xe9 vzkazy. U\u017e tu chyb\xed jen stra\u0161idlo.\u201c"],t.s)
B.b1C=new A.a6(B.aP,B.ade,!1)
B.akD=new A.aW("Z chodby se ozve tich\xe9 \u0161ust\u011bn\xed dlouh\xfdch sukn\xed. A pak ospal\xfd \u0161epot, tak tich\xfd, \u017ee to mohl b\xfdt i pr\u016fvan:")
B.uF=new A.kp(null,"baroness","assets/images/stories/museum/story/portrait_baroness.webp")
B.aeN=s(["\u201eRuhe\u2026\u201c"],t.s)
B.b_e=new A.a6(B.uF,B.aeN,!0)
B.a81=s(["\u201eTo je n\u011bmecky. Znamen\xe1 to\u2026 ticho.\u201c"],t.s)
B.b0G=new A.a6(B.aK,B.a81,!1)
B.alj=new A.aW("V\u0161em se zatajuje dech, proto\u017ee ta chodba je pr\xe1zdn\xe1.")
B.alk=new A.aW("D\u011bti rychle rozlo\u017e\xed pl\xe1nek na podlaze. Jen\u017ee tma na pap\xed\u0159e se pohne. P\u0159es chodby a s\xe1ly se pomalu val\xed \u010dern\xe1 mlha a schov\xe1v\xe1 cestu. Vid\u011bt je jen \u0161atna, kde pr\xe1v\u011b stoj\xed.")
B.afE=s(["\u201eK \u010demu n\xe1m je zaml\u017een\xfd pl\xe1nek? Co s t\xedm chcete d\u011blat? Hr\xe1t na schov\xe1vanou?\u201c"],t.s)
B.b_u=new A.a6(B.aP,B.afE,!1)
B.aaW=s(["\u201eTen pl\xe1nek n\xe1s n\u011bkam vede. Tak jdeme zjistit kam.\u201c"],t.s)
B.b15=new A.a6(B.aE,B.aaW,!1)
B.abP=s(["\u201eEmo, po\u010dkej\u2026 Emo!\u201c"],t.s)
B.b_D=new A.a6(B.aK,B.abP,!1)
B.a9o=s([B.al9,B.b1k,B.b1K,B.b1C,B.akD,B.b_e,B.b0G,B.alj,B.alk,B.b_u,B.b15,B.b_D],t.a)
B.b2l=new A.cv("story_03",B.a9o)
B.alO=new A.aW("Posledn\xed dve\u0159e se otev\u0159ou a na pl\xe1nku se rozz\xe1\u0159\xed nakreslen\xe1 kost. D\u011bti stoj\xed p\u0159esn\u011b tam, kam je pl\xe1nek vedl, v s\xe1le dinosaur\u016f. Sv\xedt\xed tady jen jedna lampa. Uprost\u0159ed se ve tm\u011b r\xfdsuje n\u011bco obrovsk\xe9ho.")
B.afJ=s(["\u201eEmo\u2026 to obrovsk\xe9 cosi\u2026 se pr\xe1v\u011b pohnulo?\u201c"],t.s)
B.b0W=new A.a6(B.aK,B.afJ,!1)
B.alE=new A.aW("Ze tmy se ozve tich\xe9, dlouh\xe9, kostnat\xe9 zask\u0159\xedp\xe1n\xed.")
B.a6d=s(["\u201e\u0158ekn\u011bte mi, \u017ee to byly dve\u0159e.\u201c"],t.s)
B.b1i=new A.a6(B.aP,B.a6d,!1)
B.aga=s([B.alO,B.b0W,B.alE,B.b1i],t.a)
B.b2K=new A.cv("story_04",B.aga)
B.akJ=new A.aW("Posledn\xed kost zapadne na sv\xe9 m\xedsto. Kostra se zachv\u011bje, pomalu zvedne hlavu\u2026 a uk\xe1\u017ee \u010delist\xed k p\xedskovi\u0161ti v rohu s\xe1lu.")
B.ab5=s(["\u201eEhm. D\u011bkujeme?\u201c"],t.s)
B.b_j=new A.a6(B.aE,B.ab5,!1)
B.a4Z=s(["\u201eRozum\xedm tomu spr\xe1vn\u011b, \u017ee n\xe1m pr\xe1v\u011b poradil dinosaurus?\u201c"],t.s)
B.b0l=new A.a6(B.aP,B.a4Z,!1)
B.alq=new A.aW("P\xedskovi\u0161t\u011b ale vypad\xe1 \xfapln\u011b oby\u010dejn\u011b. Hromada p\xedsku a v n\xed\u2026 nic.")
B.afV=s(["\u201e\u017d\xe1dn\xe1 cedulka. \u017d\xe1dn\xfd vzkaz. \u017d\xe1dn\xe1 \u0161ipka \u201aKl\xed\u010d je tady\u2018. To je teda pomoc.\u201c"],t.s)
B.b0s=new A.a6(B.aP,B.afV,!1)
B.a9a=s([B.akJ,B.b_j,B.b0l,B.alq,B.b0s],t.a)
B.b2N=new A.cv("story_05",B.a9a)
B.aks=new A.aW("P\xedskovi\u0161t\u011b se ot\u0159ese, zadun\xed a p\xedsek vyst\u0159el\xed a\u017e ke stropu. Kdy\u017e se prach usad\xed, le\u017e\xed uprost\u0159ed kr\xe1teru zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm vyryt\xe1 kost. Jon\xe1\u0161 vyt\xe1hne vzkaz.")
B.afl=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d.\u2018 Jen\u017ee tohle nen\xed cel\xfd kl\xed\u010d. Je to jen kus!\u201c"],t.s)
B.b1O=new A.a6(B.aK,B.afl,!1)
B.a8t=s(["\u201eTak\u017ee zbytek bude schovan\xfd n\u011bkde jinde v muzeu.\u201c"],t.s)
B.b1n=new A.a6(B.aP,B.a8t,!1)
B.akm=new A.aW("Lampa zablik\xe1 a zhasne. Ve tm\u011b se ozve dlouh\xe9, ospal\xe9 z\xedvnut\xed. Kdy\u017e se lampa znovu rozsv\xedt\xed, v s\xe1le nikdo nen\xed.")
B.acs=s(["\u201eKdo z v\xe1s to byl?\u201c"],t.s)
B.b1I=new A.a6(B.aE,B.acs,!1)
B.aez=s(["\u201eJ\xe1 ne!\u201c"],t.s)
B.b0y=new A.a6(B.aK,B.aez,!1)
B.a6Z=s([B.aks,B.b1O,B.b1n,B.akm,B.b1I,B.b0y],t.a)
B.b2R=new A.cv("story_06",B.a6Z)
B.ale=new A.aW("D\u011bti doraz\xed do dal\u0161\xedho s\xe1lu. Je chladn\xfd a tajemn\u011b tich\xfd. Jde o egyptsk\xfd s\xe1l, je pln\xfd sarkof\xe1g\u016f, mumi\xed a soch d\xe1vn\xfdch boh\u016f. Mal\xfdm oknem pod stropem dopad\xe1 m\u011bs\xed\u010dn\xed sv\u011btlo.")
B.a9P=s(["\u201eTady n\u011bkde mo\u017en\xe1 bude dal\u0161\xed kus. Jen\u017ee kde?\u201c"],t.s)
B.b_B=new A.a6(B.aK,B.a9P,!1)
B.alv=new A.aW("V rohu s\xe1lu le\u017e\xed v podlaze t\u011b\u017ek\xe1 kamenn\xe1 deska. Nehne se ani o milimetr. Ema se do n\xed op\u0159e celou vahou.")
B.abI=s(["\u201eJ\xe1 jsem v\u011bd\u011bla, \u017ee jsem m\u011bla r\xe1no sn\xedst ty dva rohl\xedky nav\xedc. \u201c"],t.s)
B.b_N=new A.a6(B.aE,B.abI,!1)
B.a4K=s([B.ale,B.b_B,B.alv,B.b_N],t.a)
B.b2v=new A.cv("story_07",B.a4K)
B.alr=new A.aW("M\u011bs\xed\u010dn\xed paprsek dopadne na vytesan\xfd symbol oka a ten se rozz\xe1\u0159\xed zlat\xfdm sv\u011btlem. K\xe1men zahu\u010d\xed, deska v rohu odjede stranou a odkryje schody. Vedou hluboko pod zem.")
B.a5m=s(["\u201eSchody do nezn\xe1ma. No jasn\u011b. Schody do cukr\xe1rny to asi nebudou, co?\u201c"],t.s)
B.b07=new A.a6(B.aP,B.a5m,!1)
B.al4=new A.aW("Jon\xe1\u0161 se zastav\xed na prvn\xedm schodu. Nohy ho necht\u011bj\xed poslechnout. Nela mu str\u010d\xed do ruky baterku.")
B.a6K=s(["\u201eSpr\xe1vn\xfd gentleman jde p\u0159ece prvn\xed, ne?\u201c"],t.s)
B.b_Y=new A.a6(B.aP,B.a6K,!1)
B.all=new A.aW("Jon\xe1\u0161 se zhluboka nadechne.")
B.a5A=s(["\u201eD-dob\u0159e. Jdu prvn\xed. Rychle, ne\u017e si to rozmysl\xedm.\u201c"],t.s)
B.b0v=new A.a6(B.aK,B.a5A,!1)
B.a9t=s([B.alr,B.b07,B.al4,B.b_Y,B.all,B.b0v],t.a)
B.b2B=new A.cv("story_08",B.a9t)
B.al_=new A.aW("Dole je hrobka. Je tu dusno, tma a ticho. Najednou to v\u0161ude zachrast\xed. Ze tmy vyb\u011bhnou drobn\xed brouci a rozprchnou se po cel\xe9 hrobce.")
B.ad7=s(["\u201eFuj! Brouci! \u017div\xed brouci!\u201c"],t.s)
B.b_b=new A.a6(B.aK,B.ad7,!1)
B.a5Y=s(["\u201eKlid, Jon\xe1\u0161i. Jsou to jen brouci.\u201c"],t.s)
B.b_v=new A.a6(B.aE,B.a5Y,!1)
B.a6y=s(["\u201eTo jsou skarabeov\xe9. Posv\xe1tn\xed brouci Egyp\u0165an\u016f. Ale je mi jedno, jak moc jsou posv\xe1tn\xed. Hlavn\u011b a\u0165 mi nelezou do bot.\u201c"],t.s)
B.b_h=new A.a6(B.aK,B.a6y,!1)
B.adh=s(["\u201eJon\xe1\u0161i, te\u010f se neh\xfdbej. Jeden ti sed\xed na hlav\u011b.\u201c"],t.s)
B.b0Q=new A.a6(B.aP,B.adh,!1)
B.a8d=s(["\u201eCo\u017ee?! Sundejte ho! Sundejte ho ze m\u011b!\u201c"],t.s)
B.b_P=new A.a6(B.aK,B.a8d,!1)
B.a6l=s(["\u201eD\u011bl\xe1m si legraci.\u201c"],t.s)
B.b0n=new A.a6(B.aP,B.a6l,!1)
B.a6C=s([B.al_,B.b_b,B.b_v,B.b_h,B.b0Q,B.b_P,B.b0n],t.a)
B.b2y=new A.cv("story_09",B.a6C)
B.akp=new A.aW("V\xedr v m\xedse se zpomal\xed, zastav\xed a zmiz\xed. T\u011b\u017ek\xe9 v\xedko se se sk\u0159\xedp\u011bn\xedm odsune stranou. Pod n\xedm vedou schody je\u0161t\u011b o n\u011bco hloub\u011bji.")
B.a75=s(["\u201eMuzeum m\xe1 v\xedc pater pod zem\xed ne\u017e nad n\xed. To n\xe1m nikdo na prohl\xeddce ne\u0159ekl. Asi pod\xe1m st\xed\u017enost.\u201c"],t.s)
B.b_O=new A.a6(B.aP,B.a75,!1)
B.alH=new A.aW("D\u011bti slezou dol\u016f a ocitnou se v mal\xe9m s\xe1le. \u017d\xe1dn\xe9 dve\u0159e. Nic. Jen k\xe1men a ticho.")
B.a8O=s(["\u201eNic tu nen\xed. Poj\u010fme rad\u0161i zp\xe1tky nahoru, dokud je\u0161t\u011b m\u016f\u017eeme.\u201c"],t.s)
B.b1N=new A.a6(B.aK,B.a8O,!1)
B.afA=s(["\u201eNikam nejdeme. Tady n\u011bco mus\xed b\xfdt.\u201c"],t.s)
B.b03=new A.a6(B.aE,B.afA,!1)
B.a9p=s(["\u201eV pohod\u011b. Jsme jen hluboko pod zem\xed, v s\xe1le bez dve\u0159\xed, uprost\u0159ed noci, v muzeu, kter\xe9 n\xe1s nechce pustit. Co by se asi tak mohlo st\xe1t?\u201c"],t.s)
B.b__=new A.a6(B.aP,B.a9p,!1)
B.a3Y=s([B.akp,B.b_O,B.alH,B.b1N,B.b03,B.b__],t.a)
B.b2O=new A.cv("story_10",B.a3Y)
B.alm=new A.aW("Pod prvn\xedm podstavcem se otev\u0159ou padac\xed dv\xed\u0159ka. Podstavec propadne do tmy a z jeho m\xedsta pomalu vystoup\xed zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm oko.")
B.agc=s(["\u201eDal\u0161\xed kus!\u201c"],t.s)
B.b1h=new A.a6(B.aK,B.agc,!1)
B.a6F=s(["\u201eVid\xedte? Pohoda. Tohle d\xe1me levou zadn\xed.\u201c"],t.s)
B.b0O=new A.a6(B.aE,B.a6F,!1)
B.akq=new A.aW("D\u011bti vy\u0161plhaj\xed zp\xe1tky nahoru. Potom se odn\u011bkud z d\xe1lky ozve kovov\xe9 \u0159in\u010den\xed a slab\xfd, chraplav\xfd hlas:")
B.aq=new A.kp(null,"clockmaker","assets/images/stories/museum/story/portrait_clockmaker.webp")
B.a5q=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo? Pros\xedm v\xe1s\u2026 kolik je hodin?\u201c"],t.s)
B.b1M=new A.a6(B.aq,B.a5q,!0)
B.alF=new A.aW("Hlas jde z ryt\xed\u0159sk\xe9ho s\xe1lu. Vstupn\xed chodbu ale zav\xedr\xe1 t\u011b\u017ek\xe1 \u017eelezn\xe1 m\u0159\xed\u017e. Za m\u0159\xed\u017e\xed je tma a v t\xe9 tm\u011b n\u011bkdo je.")
B.acp=s(["\u201eKone\u010dn\u011b! Lid\xe9! Ne\u0159\xedkejte mi, \u017ee se mi jenom zd\xe1te.\u201c"],t.s)
B.b_d=new A.a6(B.aq,B.acp,!0)
B.aeB=s(["\u201eKdo jste?\u201c"],t.s)
B.b0D=new A.a6(B.aE,B.aeB,!1)
B.a5M=s(["\u201eTo je velmi dobr\xe1 ot\xe1zka. A\u017e na to p\u0159ijdu, \u0159eknu v\xe1m to.\u201c"],t.s)
B.b0K=new A.a6(B.aq,B.a5M,!0)
B.ali=new A.aW("D\u011bti se chyt\xed m\u0159\xed\u017ee a zat\xe1hnou ze v\u0161ech sil. Tla\u010d\xed, lomcuj\xed s n\xed, ale m\u0159\xed\u017e se nehne ani o kousek.")
B.aad=s([B.alm,B.b1h,B.b0O,B.akq,B.b1M,B.alF,B.b_d,B.b0D,B.b0K,B.ali],t.a)
B.b2s=new A.cv("story_11",B.aad)
B.alh=new A.aW("M\u0159\xed\u017e s rachotem vyjede vzh\u016fru a v chodb\u011b se rozsv\xedt\xed. Na zemi tam sed\xed star\xfd mu\u017e v pracovn\xed z\xe1st\u011b\u0159e. Na nose m\xe1 br\xfdle, na \u010dele hodin\xe1\u0159skou lupu a ve vlasech pavu\u010dinu.")
B.a8b=s(["\u201eD\u011bkuji. Mnohokr\xe1t d\u011bkuji. Kolik je hodin?\u201c"],t.s)
B.b08=new A.a6(B.aq,B.a8b,!1)
B.al5=new A.aW("Nela se pod\xedv\xe1 na mobil.")
B.acD=s(["\u201eNev\xedm. Mobily ukazuj\xed 00:00, vypad\xe1 to, \u017ee se zasekly.\u201c"],t.s)
B.b0c=new A.a6(B.aP,B.acD,!1)
B.afW=s(["\u201ePo\u0159\xe1d p\u016flnoc? To je zvl\xe1\u0161tn\xed. Kdy\u017e mne sem n\u011bkdo zav\u0159el, zastavily se v\u0161echny hodiny p\u0159esn\u011b o p\u016flnoci. Bim, bam! Kukuk! Pardon. To se mi te\u010f n\u011bjak st\xe1v\xe1.\u201c"],t.s)
B.b1L=new A.a6(B.aq,B.afW,!1)
B.akZ=new A.aW("Jon\xe1\u0161 uk\xe1\u017ee na z\xe1st\u011bru.")
B.aa8=s(["\u201eTady m\xe1te jmenovku. \u201aMistr Vav\u0159inec Tikal, hodin\xe1\u0159 muzea.\u2018\u201c"],t.s)
B.b0r=new A.a6(B.aK,B.aa8,!1)
B.acW=s(["\u201eVav\u0159inec Tikal! No jist\u011b, to jsem j\xe1! J\xe1 tu\u0161il, \u017ee m\xe1m n\u011bco spole\u010dn\xe9ho s hodinami.\u201c"],t.s)
B.b1b=new A.a6(B.aq,B.acW,!1)
B.a6A=s([B.alh,B.b08,B.al5,B.b0c,B.b1L,B.akZ,B.b0r,B.b1b],t.a)
B.b2p=new A.cv("story_12",B.a6A)
B.ag7=s(["\u201eV. T.! To vy jste napsal ten vzkaz!\u201c"],t.s)
B.b0F=new A.a6(B.aE,B.ag7,!1)
B.akH=new A.aW("Jon\xe1\u0161 mu uk\xe1\u017ee vzkaz ze \u0161atny. Hodin\xe1\u0159 zbledne.")
B.afx=s(["\u201eTo je opravdu moje p\xedsmo. Krasopis! Jedni\u010dka s hv\u011bzdi\u010dkou! Ale kdy bych to psal? A pro\u010d?\u201c"],t.s)
B.b1A=new A.a6(B.aq,B.afx,!1)
B.a5Q=s(["\u201eA kdo v\xe1s zav\u0159el?\u201c"],t.s)
B.b_C=new A.a6(B.aE,B.a5Q,!1)
B.aeR=s(["\u201eJedna pan\xed. Byla kr\xe1sn\xe1, ale hrozn\u011b unaven\xe1. Nab\xeddla mi \u0161\xe1lek \u010daje a pak\u2026 u\u017e si nepamatuju nic, jen to, jak se usm\xedvala.\u201c"],t.s)
B.b_Z=new A.a6(B.aq,B.aeR,!1)
B.akw=new A.aW("V\u0161ichni se na sebe pod\xedvaj\xed. Nikdo nic ne\u0159ekne. Ale ka\u017ed\xfd mysl\xed na tot\xe9\u017e. Hodin\xe1\u0159 se zvedne, opr\xe1\u0161\xed si z\xe1st\u011bru a zam\xed\u0159\xed s nimi k hlavn\xedmu s\xe1lu. P\u0159ed n\xedm v\u0161ak jsou ryt\xed\u0159i v pln\xe9 zbroji. Stoj\xed bok po boku a nikoho nepust\xed d\xe1l.")
B.a9e=s(["\u201eAch, p\xe1nov\xe9 ryt\xed\u0159i. Velmi d\u016fstojn\xed. A velmi tvrdohlav\xed.\u201c"],t.s)
B.b_r=new A.a6(B.aq,B.a9e,!1)
B.akV=new A.aW("Nela zaklepe na brn\u011bn\xed.")
B.a67=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo?\u201c"],t.s)
B.b0X=new A.a6(B.aP,B.a67,!1)
B.aky=new A.aW("Brn\u011bn\xed dut\u011b zadun\xed. Ale \u017e\xe1dn\xfd z nich se ani nehne.")
B.add=s([B.b0F,B.akH,B.b1A,B.b_C,B.b_Z,B.akw,B.b_r,B.akV,B.b0X,B.aky],t.a)
B.b2t=new A.cv("story_13",B.add)
B.ala=new A.aW("Ryt\xed\u0159i jeden po druh\xe9m zasalutuj\xed a ustoup\xed stranou.")
B.aa0=s(["\u201eOni n\xe1m zasalutovali! Vid\u011bli jste to? Zasalutovali!\u201c"],t.s)
B.b10=new A.a6(B.aE,B.aa0,!1)
B.agn=s(["\u201eRyt\xed\u0159sk\xe1 \u010dest. Pozor! Pohov! R\xe1z, dva, r\xe1z, dva! J\xe1 bych byl dobr\xfd ryt\xed\u0159. Jen by m\u011b ta zbroj tla\u010dila.\u201c"],t.s)
B.b_5=new A.a6(B.aq,B.agn,!1)
B.a6g=s(["\u201eJe v po\u0159\xe1dku?\u201c"],t.s)
B.b1f=new A.a6(B.aP,B.a6g,!1)
B.agt=s(["\u201eTen \u010daj byl asi hodn\u011b siln\xfd.\u201c"],t.s)
B.b0H=new A.a6(B.aK,B.agt,!1)
B.akn=new A.aW("V\u0161ichni pokra\u010duj\xed d\xe1l do obrovsk\xe9ho s\xe1lu. Je v n\u011bm \u0161ero a podlaha pod nohama zlov\u011bstn\u011b vr\u017ee.")
B.a9v=s(["\u201eTuhle podlahu jsem\u2026 opravoval. Nebo jsem ji\u2026 hmm. Tady bych na va\u0161em m\xedst\u011b \u0161el opatrn\u011b. Nev\xedm pro\u010d. Ale \u0161el bych.\u201c"],t.s)
B.b11=new A.a6(B.aq,B.a9v,!1)
B.a6T=s(["\u201eTo je stra\u0161n\u011b uklid\u0148uj\xedc\xed.\u201c"],t.s)
B.b_R=new A.a6(B.aP,B.a6T,!1)
B.a4b=s([B.ala,B.b10,B.b_5,B.b1f,B.b0H,B.akn,B.b11,B.b_R],t.a)
B.b2S=new A.cv("story_14",B.a4b)
B.akE=new A.aW("Deska se ot\u0159ese a pole se jedno po druh\xe9m propadaj\xed do tmy. K\u016f\u0148 stihne na posledn\xed chv\xedli odsko\u010dit do bezpe\u010d\xed. Z temn\xe9 j\xe1my vylet\xed zlat\xfd \xfalomek kl\xed\u010de se \u0161t\xedtem.")
B.a8F=s(["\u201eBum! To byla ale kr\xe1sa!\u201c"],t.s)
B.b02=new A.a6(B.aq,B.a8F,!1)
B.alA=new A.aW("V\u0161ichni se na n\u011bj pod\xedvaj\xed.")
B.a5a=s(["\u201e\u2026Ehm. Pardon. Chci \u0159\xedct: to bylo velmi nebezpe\u010dn\xe9.\u201c"],t.s)
B.b1o=new A.a6(B.aq,B.a5a,!1)
B.aeH=s(["\u201eA dal\u0161\xed kus.\u201c"],t.s)
B.b_V=new A.a6(B.aK,B.aeH,!1)
B.afj=s(["\u201eA kolik jich jako je\u0161t\u011b m\xe1 b\xfdt?\u201c"],t.s)
B.b1u=new A.a6(B.aP,B.afj,!1)
B.alw=new A.aW("Hodin\xe1\u0159 prom\u011b\u0159uje \xfalomek lupou.")
B.a9I=s(["\u201eKl\xed\u010d\u2026 To je moje pr\xe1ce. Tenhle kl\xed\u010d jsem kdysi vyrobil. Pro\u010d je ulomen\xfd? Kdo by\u2026 Ach ne.\u201c"],t.s)
B.b_q=new A.a6(B.aq,B.a9I,!1)
B.acE=s([B.akE,B.b02,B.alA,B.b1o,B.b_V,B.b1u,B.alw,B.b_q],t.a)
B.b2m=new A.cv("story_15",B.acE)
B.alN=new A.aW("Cesta k dal\u0161\xedmu s\xe1lu vede p\u0159es vstupn\xed halu. Kolem obrazu baronky proch\xe1zej\xed po \u0161pi\u010dk\xe1ch. Jon\xe1\u0161 se nechce d\xedvat, ale nakonec se stejn\u011b pod\xedv\xe1. Obraz je pr\xe1zdn\xfd. Z\u016fstalo jen osam\u011bl\xe9 k\u0159eslo.")
B.aeZ=s(["\u201eKde je?\u201c"],t.s)
B.b_s=new A.a6(B.aK,B.aeZ,!1)
B.aly=new A.aW("Jon\xe1\u0161 mrkne. A baronka je zase zp\u011bt v obraze. Sp\xed a usm\xedv\xe1 se\u2026")
B.aaG=s(["\u201eTo je ona. Pan\xed baronka.\u201c"],t.s)
B.b1e=new A.a6(B.aq,B.aaG,!1)
B.aeG=s(["\u201eTo ona je ta pan\xed s \u010dajem? Ona v\xe1s zav\u0159ela?\u201c"],t.s)
B.b0A=new A.a6(B.aE,B.aeG,!1)
B.a78=s(["\u201eMo\u017en\xe1\u2026 Nev\xedm. Moje hlava je sam\xe1 d\xedra\u2026 jako ement\xe1l.\u201c"],t.s)
B.b_p=new A.a6(B.aq,B.a78,!1)
B.a72=s(["\u201eAle vy jste p\u0159ece ten kl\xed\u010d vyrobil. Kdy\u017e si vzpomenete, zjist\xedme, kde je zbytek!\u201c"],t.s)
B.b_S=new A.a6(B.aE,B.a72,!1)
B.aek=s(["\u201eAlchymista m\u011bl naho\u0159e ve v\u011b\u017ei svou laborato\u0159. On m\u011bl v\u017edycky l\xe9k na v\u0161echno.\u201c"],t.s)
B.b_x=new A.a6(B.aq,B.aek,!1)
B.aan=s(["\u201eDob\u0159e, jdeme tam.\u201c"],t.s)
B.aZT=new A.a6(B.aE,B.aan,!1)
B.alb=new A.aW("Hodin\xe1\u0159 vede d\u011bti po to\u010dit\xfdch schodech nahoru do v\u011b\u017ee, do laborato\u0159e star\xe9ho alchymisty. V laborato\u0159i je ticho a v\u0161ude le\u017e\xed prach.")
B.a4H=s(["\u201eTak, pane alchymisto. Kde m\xe1te ten l\xe9k na v\u0161echno?\u201c"],t.s)
B.b1D=new A.a6(B.aE,B.a4H,!1)
B.a47=s([B.alN,B.b_s,B.aly,B.b1e,B.b0A,B.b_p,B.b_S,B.b_x,B.aZT,B.alb,B.b1D],t.a)
B.b2P=new A.cv("story_16",B.a47)
B.akR=new A.aW("V knize jsou t\u0159i recepty. Tenebrikus je lektvar no\u010dn\xedho vid\u011bn\xed. Ardeon je lektvar odvahy. A Siderion je elix\xedr hv\u011bzdn\xe9ho sv\u011btla. Pod n\xe1zvem je drobn\xe9 p\xedsmo.")
B.a8Y=s(["\u201e\u201aRozjasn\xed mysl a vr\xe1t\xed ztracen\xe9 vzpom\xednky. Spr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch. Polovina d\xe1vky rozjasn\xed mysl. Cel\xe1 d\xe1vka usp\xed na sto let.\u2018\u201c"],t.s)
B.b1J=new A.a6(B.aK,B.a8Y,!1)
B.aku=new A.aW("Kdy\u017e se obr\xe1t\xed posledn\xed list, le\u017e\xed na n\u011bm zlat\xfd \xfalomek kl\xed\u010de s hv\u011bzdou.")
B.afR=s(["\u201eDal\u0161\xed kus kl\xed\u010de! A k tomu recept na pam\u011b\u0165. Dneska m\xe1me \u0161\u0165astn\xfd den.\u201c"],t.s)
B.b_z=new A.a6(B.aE,B.afR,!1)
B.aee=s(["\u201eEmo, jsme zav\u0159en\xed v muzeu.\u201c"],t.s)
B.b16=new A.a6(B.aP,B.aee,!1)
B.a8I=s(["\u201e\u0160\u0165astn\xfd den v r\xe1mci mo\u017enost\xed.\u201c"],t.s)
B.b0E=new A.a6(B.aE,B.a8I,!1)
B.adv=s(["\u201e\u201aSpr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch.\u2018 Hv\u011bzdy ale odsud v\u016fbec nejsou vid\u011bt.\u201c"],t.s)
B.b_X=new A.a6(B.aK,B.adv,!1)
B.akN=new A.aW("Nela uk\xe1\u017ee na \xfazk\xe9 sch\u016fdky v rohu.")
B.abf=s(["\u201eCo zkusit schody?\u201c"],t.s)
B.b01=new A.a6(B.aP,B.abf,!1)
B.akt=new A.aW("Sch\u016fdky vedou a\u017e na sam\xfd vrchol v\u011b\u017ee, do mal\xe9 hv\u011bzd\xe1rny. Za velk\xfdm oknem z\xe1\u0159\xed tis\xedce hv\u011bzd.")
B.a5i=s(["\u201eV\u017edy\u0165 je tu milion hv\u011bzd. Co s t\xedm m\xe1me d\u011blat?\u201c"],t.s)
B.b0T=new A.a6(B.aK,B.a5i,!1)
B.a5O=s([B.akR,B.b1J,B.aku,B.b_z,B.b16,B.b0E,B.b_X,B.akN,B.b01,B.akt,B.b0T],t.a)
B.b2U=new A.cv("story_17",B.a5O)
B.alD=new A.aW("Souhv\u011bzd\xed na obloze se rozz\xe1\u0159\xed a do v\u011b\u017ee padne st\u0159\xedbrn\xe9 hv\u011bzdn\xe9 sv\u011btlo. Pomalu sklouzne po schodech dol\u016f, a\u017e do alchymistovy laborato\u0159e.")
B.a3V=s(["\u201eTak\u017ee te\u010f asi ty hv\u011bzdy sv\xedt\xed spr\xe1vn\u011b. Kdo by \u0159ekl, \u017ee jdou hv\u011bzdy zapnout.\u201c"],t.s)
B.b0g=new A.a6(B.aP,B.a3V,!1)
B.akx=new A.aW("D\u011bti jdou za sv\u011btlem do laborato\u0159e.")
B.aa7=s(["\u201eMn\u011b se to tu nel\xedb\xed. N\u011bkdo n\xe1s tu nechce, c\xedt\xedm to.\u201c"],t.s)
B.b0m=new A.a6(B.aK,B.aa7,!1)
B.a6R=s(["\u201eAlchymista m\xedval v\u0161echno p\u0159ipraven\xe9 dop\u0159edu. Jestli ten l\xe9k n\u011bkde bude, tak ur\u010dit\u011b tady.\u201c"],t.s)
B.b0p=new A.a6(B.aq,B.a6R,!1)
B.a6i=s([B.alD,B.b0g,B.akx,B.b0m,B.b0p],t.a)
B.b2k=new A.cv("story_18",B.a6i)
B.akY=new A.aW("Hodin\xe1\u0159 vypije odm\u011b\u0159enou polovinu elix\xedru. \u0160kytne a v o\u010d\xedch mu zajisk\u0159\xed drobn\xe9 hv\u011bzdi\u010dky.")
B.acJ=s(["\u201eLevandule! Ten \u010daj byl levandulov\xfd. A ona \u0159\xedkala: \u201aBu\u010fte tak laskav, mist\u0159e Tikale. Jenom zastavte hodiny. Jenom na chvilku.\u2018 Potom za\u0161eptala: \u201aJenom nav\u017edy.\u2018 Myslel jsem, \u017ee jsem \u0161patn\u011b rozum\u011bl. A pak\u2026 u\u017e si nic nepamatuju.\u201c"],t.s)
B.b_M=new A.a6(B.aq,B.acJ,!1)
B.aaA=s(["\u201eJak\xe9 hodiny?\u201c"],t.s)
B.b1H=new A.a6(B.aK,B.aaA,!1)
B.a7S=s(["\u201eTo je\u0161t\u011b nev\xedm. Ale v\xedm, kde to zjist\xedme.\u201c"],t.s)
B.b1y=new A.a6(B.aq,B.a7S,!1)
B.alI=new A.aW("Druhou polovinu elix\xedru hodin\xe1\u0159 pe\u010dliv\u011b zaz\xe1tkuje a schov\xe1 do kapsy z\xe1st\u011bry.")
B.a9z=s(["\u201eNa hor\u0161\xed \u010dasy.\u201c"],t.s)
B.b_o=new A.a6(B.aq,B.a9z,!1)
B.alJ=new A.aW("V tu chv\xedli se ze schodi\u0161t\u011b pod nimi oz\xfdv\xe1 tich\xe9 \u0161ust\u011bn\xed. Pomal\xfdmi kroky jde n\u011bkdo nahoru. V d\xe1lce se oz\xfdv\xe1 ospal\xfd hlas:")
B.ad2=s(["\u201eWas ist das\u2026? Kdo m\u011b to zase ru\u0161\xed\u2026? Ruhe\u2026 Ruhe\u2026\u201c"],t.s)
B.b13=new A.a6(B.uF,B.ad2,!0)
B.abl=s([B.akY,B.b_M,B.b1H,B.b1y,B.alI,B.b_o,B.alJ,B.b13],t.a)
B.b2F=new A.cv("story_19",B.abl)
B.alG=new A.aW("Kroky se zastav\xed za dve\u0159mi a v\u0161ichni ztuhnou. Ozve se jen dlouh\xe9, ospal\xe9 z\xedvnut\xed. Pak \u0161ust\u011bn\xed sukn\xed pomalu sl\xe1bne, a\u017e utichne \xfapln\u011b.")
B.acP=s(["\u201eJe pry\u010d. Vr\xe1tila se do obrazu. O\u010dividn\u011b moc dlouho venku nevydr\u017e\xed.\u201c"],t.s)
B.b1S=new A.a6(B.aK,B.acP,!1)
B.a91=s(["\u201eTak toho vyu\u017eijeme. Rychle dol\u016f!\u201c"],t.s)
B.b0B=new A.a6(B.aE,B.a91,!1)
B.al6=new A.aW("D\u011bti jdou tmou za hodin\xe1\u0159em. Vede je dlouhou chodbou a\u017e k n\xedzk\xfdm dve\u0159\xedm.")
B.a7d=s(["\u201eMoje d\xedlna! Kdo mi tady ud\u011blal takov\xfd nepo\u0159\xe1dek? Aha. J\xe1. Tady b\xfdval v\u017edycky po\u0159\xe1dek. Ka\u017ed\xe9 hodiny v\u011bd\u011bly, kolik je hodin. Te\u010f nev\u011bd\xed nic. Ani jedny. Jako j\xe1.\u201c"],t.s)
B.b_0=new A.a6(B.aq,B.a7d,!1)
B.ab1=s([B.alG,B.b1S,B.b0B,B.al6,B.b_0],t.a)
B.b2D=new A.cv("story_20",B.ab1)
B.ako=new A.aW("N\xe1st\u011bnn\xe9 hodiny odbij\xed p\u016flnoc a v\u0161echny bud\xedky se ozvou s nimi. Zvon\xed, cinkaj\xed a rachot\xed. Pak v\u0161echny zase ztichnou a ru\u010di\u010dky se znovu zastav\xed. A na podlaze pod pracovn\xedm stolem n\u011bco le\u017e\xed.")
B.agb=s(["\u201eMoje bed\xfdnka! Moje sou\u010d\xe1stky! Pades\xe1t let jsem je t\u0159\xeddil!\u201c"],t.s)
B.b0o=new A.a6(B.aq,B.agb,!1)
B.alc=new A.aW("Hodin\xe1\u0159 si k bed\xfdnce klekne a n\u011b\u017en\u011b ji hlad\xed.")
B.a7J=s(["\u201eTahle bed\xfdnka byla v\u017edycky na sv\xe9m m\xedst\u011b. A v\u0161echno v n\xed taky.\u201c"],t.s)
B.b17=new A.a6(B.aq,B.a7J,!1)
B.aax=s([B.ako,B.b0o,B.alc,B.b17],t.a)
B.b2Q=new A.cv("story_21",B.aax)
B.al1=new A.aW("Posledn\xed sou\u010d\xe1stka zapadne na sv\xe9 m\xedsto a pod bed\xfdnkou se zaleskne zlat\xfd \xfalomek kl\xed\u010de s kole\u010dkem. Hodin\xe1\u0159 vezme bed\xfdnku do rukou. Chv\xedli se na ni d\xedv\xe1. A pak se mu v o\u010d\xedch rozsv\xedt\xed. Tentokr\xe1t doopravdy.")
B.a6B=s(["\u201eU\u017e si vzpom\xedn\xe1m. Na v\u0161echno. Za orlojem je tajn\xe1 chodba, kter\xe1 vede k srdci muzea.\u201c"],t.s)
B.b_9=new A.a6(B.aq,B.a6B,!1)
B.agw=s(["\u201eBaronka m\u011b p\u0159inutila ho zastavit a zape\u010detit. Od t\xe9 chv\xedle je tu po\u0159\xe1d p\u016flnoc. R\xe1no nikdy nep\u0159ijde a dve\u0159e se nikdy neotev\u0159ou.\u201c"],t.s)
B.b0M=new A.a6(B.aq,B.agw,!1)
B.aeC=s(["\u201eA kl\xed\u010d?\u201c"],t.s)
B.b0b=new A.a6(B.aK,B.aeC,!1)
B.a8w=s(["\u201eTen rozlomila ona. Kousek po kousku roznesla \xfalomky po muzeu a u ka\u017ed\xe9ho nastra\u017eila past, aby u\u017e nikdo nemohl srdce muzea znovu probudit. A j\xe1 hlup\xe1k j\xed je\u0161t\u011b sv\xedtil na cestu.\u201c"],t.s)
B.b_U=new A.a6(B.aq,B.a8w,!1)
B.a3s=s(["\u201eJen jednou se mi na chv\xedli rozjasnilo v hlav\u011b. Rychle jsem napsal vzkaz a schoval ho do sk\u0159\xed\u0148ky v \u0161atn\u011b, kde by ho baronka nikdy nehledala. Stihl jsem to t\u011bsn\u011b p\u0159edt\xedm, ne\u017e mi poru\u010dila, a\u0165 se zav\u0159u za m\u0159\xed\u017e. A pak u\u017e jsem si nepamatoval nic.\u201c"],t.s)
B.b0I=new A.a6(B.aq,B.a3s,!1)
B.agg=s(["\u201eAle pro\u010d to ud\u011blala?\u201c"],t.s)
B.b0V=new A.a6(B.aE,B.agg,!1)
B.a5z=s([B.al1,B.b_9,B.b0M,B.b0b,B.b_U,B.b0I,B.b0V],t.a)
B.b2V=new A.cv("story_22",B.a5z)
B.aeI=s(["\u201eZ\xedtra r\xe1no ji maj\xed odv\xe9zt do nov\xe9 galerie na n\xe1dra\u017e\xed. Mezi vlaky, hl\xe1\u0161en\xed a tis\xedce lid\xed. L\xe9ta tady nem\u016f\u017ee usnout kv\u016fli n\xe1v\u0161t\u011bvn\xedk\u016fm. A tam by neusnula u\u017e nikdy.\u201c"],t.s)
B.b0P=new A.a6(B.aq,B.aeI,!1)
B.a9u=s(["\u201eTo je vlastn\u011b\u2026 trochu smutn\xe9.\u201c"],t.s)
B.b_2=new A.a6(B.aE,B.a9u,!1)
B.aes=s(["\u201eJen\u017ee j\xed je \xfapln\u011b jedno, \u017ee tu n\u011bkoho zamkne. A \u017ee se muzeum u\u017e nikdy neotev\u0159e. To je teda p\u011bkn\u011b sobeck\xe9.\u201c"],t.s)
B.b_7=new A.a6(B.aP,B.aes,!1)
B.akT=new A.aW("Hodin\xe1\u0159 je zavede do rohu d\xedlny. Stoj\xed tam orloj, na kter\xe9m hodin\xe1\u0159 pracoval cel\xfd \u017eivot. Te\u010f ml\u010d\xed.")
B.a96=s(["\u201eMoje nejkr\xe1sn\u011bj\u0161\xed pr\xe1ce. A cesta k srdci muzea. Jen\u017ee jsem ho musel rozebrat.\u201c"],t.s)
B.b_I=new A.a6(B.aq,B.a96,!1)
B.acu=s(["\u201eTak to oprav\xedme. Ur\u010dit\u011b to nebude t\u011b\u017ek\xe9.\u201c"],t.s)
B.b_m=new A.a6(B.aE,B.acu,!1)
B.a76=s(["\u201eTo sam\xe9 jsi \u0159\xedkala o tom pl\xe1nu se \u0161atnou. A pod\xedvej, kde jsme.\u201c"],t.s)
B.b0x=new A.a6(B.aP,B.a76,!1)
B.a86=s([B.b0P,B.b_2,B.b_7,B.akT,B.b_I,B.b_m,B.b0x],t.a)
B.b2G=new A.cv("story_23",B.a86)
B.akQ=new A.aW("Orloj se nadechne. Ru\u010di\u010dky se rozeb\u011bhnou a dv\xed\u0159ka dole se pomalu otev\u0159ou. Za nimi je \xfazk\xe1 chodba a na jej\xedm konci podivn\xe9 sv\u011btlo.")
B.afz=s(["\u201eTajn\xe1 chodba! Poj\u010fte!\u201c"],t.s)
B.b_t=new A.a6(B.aE,B.afz,!1)
B.alz=new A.aW("Chodba za orlojem kon\u010d\xed ve skryt\xe9 hale s vysok\xfdm stropem. Uprost\u0159ed zdi vis\xed obrovsk\xe9 hodiny, p\u0159es cifern\xedk maj\xed rudou pe\u010de\u0165.")
B.ae1=s(["\u201eSrdce muzea.\u201c"],t.s)
B.b0J=new A.a6(B.aq,B.ae1,!1)
B.akU=new A.aW("Za jejich z\xe1dy za\u0161ust\xed \u0161aty.")
B.alK=new A.aW("Ve dve\u0159\xedch haly stoj\xed baronka Frida von Schlafenberg. Skute\u010dn\xe1 a \u017eiv\xe1, vystoupila z obrazu. Je mnohem vy\u0161\u0161\xed, ne\u017e si mysleli. A hrozn\u011b, hrozn\u011b ospal\xe1.")
B.acK=s(["\u201eKinder\u2026 D\u011bti. Pro\u010d jste tak hlu\u010dn\xe9? Sto let. Sto let jsem neusnula. Nechte ty hodiny sp\xe1t. Bitte\u2026\u201c"],t.s)
B.b0_=new A.a6(B.uF,B.acK,!1)
B.alB=new A.aW("Ema ud\u011bl\xe1 krok dop\u0159edu a postav\xed se p\u0159ed ostatn\xed. Baronka k n\xed nat\xe1hne ruku. Ale v p\u016fli pohybu se j\xed zav\u0159ou o\u010di. Pomalu se sesune na schod, polo\u017e\xed hlavu na ruku\u2026 a usne. Jej\xed postava zbledne, zpr\u016fhledn\xed a rozplyne se.")
B.a9n=s(["\u201eVr\xe1tila se do obrazu?\u201c"],t.s)
B.b1s=new A.a6(B.aP,B.a9n,!1)
B.a6Y=s(["\u201eVypad\xe1 to tak. Ale nev\xedme, na jak dlouho.\u201c"],t.s)
B.b_f=new A.a6(B.aK,B.a6Y,!1)
B.a7M=s(["\u201eTak si mus\xedme posp\xed\u0161it. Pom\u016f\u017eete star\xe9mu hodin\xe1\u0159i? Je\u0161t\u011b naposledy?\u201c"],t.s)
B.b1g=new A.a6(B.aq,B.a7M,!1)
B.afc=s([B.akQ,B.b_t,B.alz,B.b0J,B.akU,B.alK,B.b0_,B.alB,B.b1s,B.b_f,B.b1g],t.a)
B.b2i=new A.cv("story_24",B.afc)
B.akS=new A.aW("\xdalomky se zatav\xed do vosku a pe\u010de\u0165 se rozz\xe1\u0159\xed. Pak praskne a rozlet\xed se na kusy. Pod n\xed se objev\xed cifern\xedk. Ru\u010di\u010dky ukazuj\xed p\u016flnoc. Hodiny se zhluboka nadechnou\u2026 a rozb\u011bhnou se. Po cel\xe9m muzeu se rozezn\xed tik\xe1n\xed v\u0161ech hodin najednou. Ru\u010di\u010dky ute\u010dou od p\u016flnoci, v okn\u011b chodby je vid\u011bt \xfasvit a z\xe1mky v\u0161ech dve\u0159\xed v muzeu cvaknou.")
B.aec=s(["\u201eSly\u0161\xedte to? Muzeum zase d\xfdch\xe1. Srdce muzea je tajemstv\xed, nikdo ho tu nesm\xed naj\xedt a v\xe1s tak\xe9 ne. Tuhle chodbu zase schov\xe1m. Z\u016fstanu tady a d\xe1m do po\u0159\xe1dku v\u0161echno, co tu baronka provedla. Hodiny u\u017e nikomu nedovol\xedm zastavit. Ani za \u0161\xe1lek levandulov\xe9ho \u010daje.\u201c"],t.s)
B.b12=new A.a6(B.aq,B.aec,!1)
B.adf=s(["\u201eA posp\u011b\u0161te si. Baronka te\u010f tvrd\u011b sp\xed. Ale dokud je muzeum zav\u0159en\xe9, m\u016f\u017ee kdykoli vystoupit z obrazu. Otev\u0159ete hlavn\xed dve\u0159e, ne\u017e se vzbud\xed.\u201c"],t.s)
B.b0i=new A.a6(B.aq,B.adf,!1)
B.aaw=s([B.akS,B.b12,B.b0i],t.a)
B.b2C=new A.cv("story_25",B.aaw)
B.alp=new A.aW("Ema ho obejme. Jon\xe1\u0161 mu pod\xe1 ruku. Nela mu vyt\xe1hne pavu\u010dinu z vlas\u016f. Zvenku se ozve motor n\xe1kladn\xedho auta, st\u011bhov\xe1ci p\u0159ijeli pro obraz baronky. D\u011bti b\u011b\u017e\xed zp\xe1tky do vstupn\xed haly. Baronka v obraze sp\xed a usm\xedv\xe1 se. Jen\u017ee hlavn\xed dve\u0159e se po\u0159\xe1d nehnou.")
B.a7P=s(["\u201eZ\xe1mky p\u0159ece cvakly. Tak pro\u010d se ty dve\u0159e neotev\u0159ou?\u201c"],t.s)
B.b0U=new A.a6(B.aP,B.a7P,!1)
B.aeM=s(["\u201eH\xe1d\xe1m, \u017ee tohle je posledn\xed past pan\xed baronky.\u201c"],t.s)
B.aZX=new A.a6(B.aE,B.aeM,!1)
B.al2=new A.aW("Baronka v obraze se zavrt\xed a ze span\xed vzdychne. D\u011bti ztuhnou.")
B.a7x=s(["\u201eRychle. A potichu.\u201c"],t.s)
B.b0d=new A.a6(B.aE,B.a7x,!1)
B.acB=s([B.alp,B.b0U,B.aZX,B.al2,B.b0d],t.a)
B.b2L=new A.cv("story_26",B.acB)
B.alM=new A.aW("Posledn\xed z\xe1str\u010dka cvakne. T\u011b\u017ek\xe1 k\u0159\xeddla dve\u0159\xed se pomalu otev\u0159ou a do haly vtrhne rann\xed sv\u011btlo. Rozlije se po podlaze, po zdech a nakonec dopadne i na obraz.")
B.aaS=s(["\u201eJe otev\u0159eno! Muzeum je otev\u0159en\xe9!\u201c"],t.s)
B.b1P=new A.a6(B.aE,B.aaS,!1)
B.a9C=s(["\u201ePod\xedvejte na obraz. Pan\xed baronce n\u011bjak ztuhl \xfasm\u011bv.\u201c"],t.s)
B.b1t=new A.a6(B.aP,B.a9C,!1)
B.akv=new A.aW("Tv\xe1\u0159 baronky se pomalu zamra\u010d\xed. U\u017e se nepohne.")
B.a8D=s(["\u201eTak to bychom m\u011bli. A te\u010f honem pry\u010d, ne\u017e n\xe1s tu n\u011bkdo najde.\u201c"],t.s)
B.b09=new A.a6(B.aK,B.a8D,!1)
B.al3=new A.aW("D\u011bti vyklouznou z muzea ve chv\xedli, kdy st\u011bhov\xe1ci vystupuj\xed z auta.")
B.afm=s(["\u201eZvl\xe1dli jsme to!\u201c"],t.s)
B.b19=new A.a6(B.aE,B.afm,!1)
B.akO=new A.aW("St\u011bhov\xe1ci vejdou do muzea, po chv\xedli vyn\xe1\u0161\xed velk\xfd obraz zabalen\xfd do deky. Jeden roh deky sklouzne.")
B.akM=new A.aW("Baronka Frida von Schlafenberg sice sp\xed, ale tv\xe1\u0159\xed se tak na\u0161tvan\u011b jako je\u0161t\u011b nikdy. V\u0161imnou si toho i st\u011bhov\xe1ci. \u201eNa n\xe1dra\u017e\xed si zvykne,\u201c prohod\xed jeden ze st\u011bhov\xe1k\u016f. Potom, co auto odjede, se v okn\u011b muzea na okam\u017eik objev\xed star\xfd hodin\xe1\u0159 s lampou. K\xfdvne na n\u011b, zamrk\xe1 a zmiz\xed. Z muzea je sly\u0161et tich\xe9, spokojen\xe9 tik\xe1n\xed.")
B.aft=s(["\u201eTohle n\xe1m nikdo neuv\u011b\u0159\xed.\u201c"],t.s)
B.b_1=new A.a6(B.aP,B.aft,!1)
B.adH=s([B.alM,B.b1P,B.b1t,B.akv,B.b09,B.al3,B.b19,B.akO,B.akM,B.b_1],t.a)
B.b2J=new A.cv("story_27",B.adH)
B.a9O=s([B.b2x,B.b2E,B.b2l,B.b2K,B.b2N,B.b2R,B.b2v,B.b2B,B.b2y,B.b2O,B.b2s,B.b2p,B.b2t,B.b2S,B.b2m,B.b2P,B.b2U,B.b2k,B.b2F,B.b2D,B.b2Q,B.b2V,B.b2G,B.b2i,B.b2C,B.b2L,B.b2J],t.WD)
B.aTr=new A.ap("sfx_forest_t01_door_open",0.26785714285714285,1,null,1)
B.a9R=s([B.ME,B.aTr],t.e)
